    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve detaylı bilginin yetkili personele iletilip iletilmediği, hata senaryoları tetiklenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi uzatılmaması, uyarı gösterilmesi, taslak kaydı ve veri kaybı olmadan devam etme akışının çalışıp çalışmadığı, sistem çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
