    {
      "requirement_id": "KDH-089",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya yükleme doğrulama, içerik denetimi ve kısıtlı izinlerle saklama işlemlerinin çalışıp çalışmadığı, zararlı ve geçerli dosyalar yükleyerek sonuçların gözlemlenmesiyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-090",
      "methods": [
        "Test"
      ],
      "rationale": "CORS politikalarının ve URL yönlendirme beyaz listesinin etkinliği, farklı kaynaklardan istekler göndererek ve yönlendirme senaryoları simüle ederek test edilmelidir."
    },
    {
      "requirement_id": "KDH-091",
      "methods": [
        "Test"
      ],
      "rationale": "Hata durumlarında güvenli duruma geçişin ve hata ayrıntılarının gizlenmesinin doğrulanması, sunucu ve ağ hataları simüle edilerek ve kullanıcıya dönen yanıtların gözlemlenmesiyle test edilir."
    },
    {
      "requirement_id": "KDH-092",
      "methods": [
        "Test"
      ],
